#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m09-shelf-rollout pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m09-shelf-rollout
CHECKS="api-deploy-exists web-deploy-exists api-image-is-v2 web-image-is-v2 rollout-history api-saw-v3-broken api-rollout-finished"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m09-shelf-rollout
checks:
  - id: api-deploy-exists
    describe: The Deployment shelf-api exists in the namespace shelf, with 3 available replicas
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: "{.status.availableReplicas}"
          equals: "3"
    hint: Apply the starting file with `kubectl apply --filename shelf-rollout/shelf-api.yaml`, and wait with `kubectl rollout status deployment/shelf-api --namespace shelf`. If the Deployment exists but has fewer than 3 available replicas, `kubectl get pods --namespace shelf` shows which Pod is not Ready.
  - id: web-deploy-exists
    describe: The Deployment shelf-web exists in the namespace shelf, with 3 available replicas
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: "{.status.availableReplicas}"
          equals: "3"
    hint: Apply `shelf-rollout/shelf-web.yaml` the same way, and wait for its rollout.
  - id: api-image-is-v2
    describe: The Pod template of shelf-api uses the image tag v2
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[0].image}
    expect:
      matches: :v2(@sha256:[a-f0-9]+)?$
    hint: After the rollback, the api must run v2, not v1 and not v3-broken. `kubectl rollout history deployment/shelf-api --namespace shelf` lists the revisions, and `kubectl rollout undo` goes back to the previous one.
  - id: web-image-is-v2
    describe: The Pod template of shelf-web uses the image tag v2
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[0].image}
    expect:
      matches: :v2(@sha256:[a-f0-9]+)?$
    hint: Change the tag in `shelf-rollout/shelf-web.yaml` from v1 to v2 and apply it again, or run `kubectl set image deployment/shelf-web web=localhost:5001/shelf/web:v2 --namespace shelf`.
  - id: rollout-history
    describe: The rollout history of shelf-api lists at least 3 revisions
    kubectl:
      - rollout
      - history
      - deployment/shelf-api
      - -n
      - shelf
    expect:
      regexCountAtLeast:
        pattern: ^\d+\s
        count: 3
    hint: Each different Pod template is one revision. Roll out v1, then v2, then v3-broken, and wait for each change to be seen before the next. A rollback to v2 reuses its ReplicaSet and keeps the count at three.
  - id: api-saw-v3-broken
    describe: The api has a ReplicaSet for the image tag v3-broken, so the bad release was rolled out
    kubectl:
      - get
      - replicaset
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-api
      - -o
      - jsonpath={.items[*].spec.template.spec.containers[0].image}
    expect:
      matches: :v3-broken
    hint: "Roll out the bad release on purpose: set the api image to localhost:5001/shelf/api:v3-broken, apply it, and watch with `kubectl rollout status deployment/shelf-api --namespace shelf` until it reports the progress deadline."
  - id: api-rollout-finished
    describe: "The rollout of shelf-api is complete: the rollback has finished and no new Pod is waiting"
    kubectl:
      - rollout
      - status
      - deployment/shelf-api
      - -n
      - shelf
      - --timeout=60s
    expect:
      exitCode: 0
    hint: "`kubectl rollout status deployment/shelf-api --namespace shelf` must end with `successfully rolled out`. While the v3-broken ReplicaSet still has a Pod, the rollout is not finished: undo it."
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
